import { readFileSync } from "node:fs";

import { describe, expect, it } from "vite-plus/test";

import { OUTPUT, readTemplateFiles, renderTemplates } from "../src/templates.ts";

describe("renderTemplates", () => {
  it("embeds each xlsx file as base64 under its name, in name order", () => {
    const files = [
      { file: "gc.xlsx", bytes: Uint8Array.of(0x50, 0x4b, 0x03) },
      { file: "dc.xlsx", bytes: Uint8Array.of(0xff) },
    ];
    expect(renderTemplates(files)).toBe(
      [
        "// Generated by tools/gen/src/templates.ts from packages/documents/templates/*.xlsx. Do not edit.",
        "export const TEMPLATES_BASE64 = {",
        '  "dc": "/w==",',
        '  "gc": "UEsD",',
        "} as const;",
        "",
      ].join("\n"),
    );
  });

  it("quotes each key, so any file name makes a valid module", () => {
    expect(renderTemplates([{ file: "sales-invoice.xlsx", bytes: Uint8Array.of(0xff) }])).toContain(
      '  "sales-invoice": "/w==",',
    );
  });

  it("the committed templates.generated.ts is fresh (run `pnpm gen:templates`)", () => {
    expect(readFileSync(OUTPUT, "utf8")).toBe(renderTemplates(readTemplateFiles()));
  });
});
